<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { api,http } from '@/api/http'
import type { PageData } from '@/types'
import { ElMessage } from 'element-plus'
const tab=ref('users'),users=ref<any[]>([]),roles=ref<any[]>([]),configs=ref<any[]>([]),audits=ref<any[]>([]),total=ref(0),page=ref(1),loading=ref(false),dialog=ref(false),selected=ref<any>(),form=reactive({role:'MEMBER',status:'ACTIVE'})
async function load(){loading.value=true;try{if(tab.value==='users'){const d=await api<PageData<any>>(http.get('/admin/users',{params:{page:page.value,pageSize:15}}));users.value=d.items;total.value=d.total}else if(tab.value==='roles')roles.value=await api(http.get('/admin/roles'));else if(tab.value==='config')configs.value=await api(http.get('/admin/config'));else{const d=await api<PageData<any>>(http.get('/admin/audits',{params:{page:page.value,pageSize:15}}));audits.value=d.items;total.value=d.total}}finally{loading.value=false}}
function editUser(row:any){selected.value=row;form.role=row.role;form.status=row.status;dialog.value=true}
async function saveUser(){await api(http.put(`/admin/users/${selected.value.id}/role-status`,form));ElMessage.success('用户角色与状态已更新，原会话已失效');dialog.value=false;load()}
async function saveConfig(row:any){await api(http.put(`/admin/config/${row.configKey}`,{value:row.configValue,description:row.description}));ElMessage.success('配置已保存')}
onMounted(load)
</script>
<template><div><div class="page-head"><div><h2>系统管理</h2><p>管理员集中维护人员权限、基础配置与操作审计。</p></div></div><section class="panel"><el-tabs v-model="tab" @tab-change="page=1;load()"><el-tab-pane label="用户管理" name="users"/><el-tab-pane label="角色权限" name="roles"/><el-tab-pane label="基础配置" name="config"/><el-tab-pane label="操作审计" name="audit"/></el-tabs><el-table v-if="tab==='users'" v-loading="loading" :data="users" stripe><el-table-column prop="username" label="用户名"/><el-table-column prop="displayName" label="姓名"/><el-table-column prop="phone" label="手机号"/><el-table-column prop="email" label="邮箱"/><el-table-column label="角色"><template #default="s"><el-tag>{{ s.row.role }}</el-tag></template></el-table-column><el-table-column label="状态"><template #default="s"><el-tag :type="s.row.status==='ACTIVE'?'success':'danger'">{{ s.row.status==='ACTIVE'?'正常':'停用' }}</el-tag></template></el-table-column><el-table-column prop="createdAt" label="创建时间"/><el-table-column label="操作" width="100"><template #default="s"><el-button link type="primary" @click="editUser(s.row)">权限设置</el-button></template></el-table-column></el-table><el-table v-else-if="tab==='roles'" :data="roles" stripe><el-table-column prop="name" label="角色" width="160"/><el-table-column prop="code" label="代码" width="200"/><el-table-column label="权限范围"><template #default="s"><el-tag v-for="p in s.row.permissions" :key="p" style="margin-right:8px">{{ p }}</el-tag></template></el-table-column></el-table><el-table v-else-if="tab==='config'" :data="configs" stripe><el-table-column prop="configKey" label="配置键" width="200"/><el-table-column label="配置值"><template #default="s"><el-input v-model="s.row.configValue"/></template></el-table-column><el-table-column prop="description" label="说明"/><el-table-column label="操作" width="90"><template #default="s"><el-button link type="primary" @click="saveConfig(s.row)">保存</el-button></template></el-table-column></el-table><el-table v-else v-loading="loading" :data="audits" stripe><el-table-column prop="createdAt" label="时间" min-width="170"/><el-table-column prop="username" label="用户" width="120"/><el-table-column prop="action" label="操作" width="180"/><el-table-column prop="resourceType" label="资源" width="130"/><el-table-column prop="resourceId" label="资源 ID" width="110"/><el-table-column prop="detail" label="详情" min-width="220" show-overflow-tooltip/><el-table-column prop="ipAddress" label="IP" width="130"/></el-table><el-pagination v-if="tab==='users'||tab==='audit'" style="margin-top:18px;justify-content:flex-end" background layout="total,prev,pager,next" :total="total" :page-size="15" v-model:current-page="page" @current-change="load"/></section><el-dialog v-model="dialog" title="用户角色与状态" width="450px"><p>{{ selected?.username }} · {{ selected?.displayName }}</p><el-form label-position="top"><el-form-item label="角色"><el-select v-model="form.role" style="width:100%"><el-option label="管理员" value="ADMIN"/><el-option label="库存管理员" value="INVENTORY_MANAGER"/><el-option label="收银员" value="CASHIER"/><el-option label="普通会员" value="MEMBER"/></el-select></el-form-item><el-form-item label="账号状态"><el-radio-group v-model="form.status"><el-radio-button value="ACTIVE">正常</el-radio-button><el-radio-button value="DISABLED">停用</el-radio-button></el-radio-group></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="saveUser">保存并使原会话失效</el-button></template></el-dialog></div></template>
